1	"use client";
2	
3	import { useMemo, useRef, useState } from "react";
4	import { useActionState, useEffect } from "react";
5	import { payAndDeploy, previewOrderCoupon } from "@/lib/actions";
6	import { AppLogo } from "@/components/ui/AppLogo";
7	import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
8	import { VersionPickerModal, type FamilyGroup } from "@/components/customer/VersionPickerModal";
9	// No vpsTermPriceCents here any more: every term price this wizard shows is now
10	// derived from lib/renewal-quote.ts (the regular/renewal rate) with the promo
11	// applied on top, so the file has exactly one source for what a term costs.
12	import { VPS_TERMS, vpsTerm, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
13	import { renewalQuote } from "@/lib/renewal-quote";
14	import { walletSplit } from "@/lib/wallet-split";
15	import {
16	  EXTRA_DISK_MAX_ADD_GB,
17	  EXTRA_DISK_MIN_GB,
18	  EXTRA_DISK_ONE_WAY_NOTE,
19	  EXTRA_DISK_STEP_GB,
20	  effectiveDiskGB,
21	  extraDiskCentsAt,
22	} from "@/lib/extra-disk";
23	import { useCurrency } from "@/components/currency/CurrencyContext";
24	import { convertAndFormat, DEFAULT_CURRENCY } from "@/lib/currency";
25	import { trackDeployStep, trackDeployError } from "@/lib/deploy-funnel-client";
26	
27	type Plan = {
28	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
29	  bandwidthTB: number; priceCents: number; storageTier: string;
30	};
31	type Image = {
32	  id: string; slug: string; name: string; category: string; family: string;
33	  version: string; logo: string; minRamMB: number; minDiskGB: number;
34	  licenseRequired: boolean; featured: boolean;
35	};
36	type NodeOpt = { id: string; name: string; publicIp: string };
37	
38	// USD formatter — this wizard's long-standing 2-decimal style ("$5.00"). Used
39	// verbatim for the USD display path (so USD renders byte-for-byte unchanged) and
40	// for the "billed in USD" reference note. `money()` (defined per-render inside the
41	// component, currency-aware) is what the UI actually calls.
42	const usd = (c: number) => `$${(c / 100).toFixed(2)}`;
43	
44	/** sessionStorage key for the in-progress order — see the restore effect below. */
45	const DRAFT_KEY = "nxeon.deploy.draft.v1";
46	type Draft = {
47	  step: number;
48	  planId: string;
49	  nodeId: string;
50	  imageId: string;
51	  tab: string;
52	  addons: { malware: boolean; backup: boolean; docker: boolean };
53	  dedicatedIp: boolean;
54	  extraDiskGB: number;
55	  hostname: string;
56	  pubKey: string;
57	  termMonths: number;
58	  useWallet: boolean;
59	};
60	
61	/** APPLICATION-category images with one of these families are split into the Games tab. */
62	const GAME_FAMILIES = new Set(["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"]);
63	
64	/** Install-step tabs. Games are peeled out of Applications into their own tab. */
65	const TABS = [
66	  { key: "os", label: "Operating Systems", match: (i: Image) => i.category === "PLAIN_OS" },
67	  { key: "panels", label: "Control Panels", match: (i: Image) => i.category === "CONTROL_PANEL" },
68	  { key: "apps", label: "Applications", match: (i: Image) => i.category === "APPLICATION" && !GAME_FAMILIES.has(i.family) },
69	  { key: "games", label: "Games", match: (i: Image) => i.category === "APPLICATION" && GAME_FAMILIES.has(i.family) },
70	] as const;
71	
72	const OS_FAMILY_NAMES: Record<string, string> = {
73	  ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
74	  fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", kali: "Kali Linux", opensuse: "openSUSE",
75	};
76	/**
77	 * Human name for an image on the confirmation screen.
78	 *
79	 * Catalogue rows carry the version in BOTH `name` ("Ubuntu 20.04") and `version`
80	 * ("20.04"), so appending unconditionally printed "Ubuntu 20.04 20.04" — on the
81	 * last screen before the customer pays. Only append a version the name does not
82	 * already end with.
83	 */
84	function imageLabel(img: Image) {
85	  const version = img.version?.trim();
86	  if (!version) return img.name;
87	  return img.name.trim().endsWith(version) ? img.name : `${img.name} ${version}`;
88	}
89	
90	/** Clean family display name (no version) for the OS family cards. */
91	function osFamilyName(img: Image) {
92	  return OS_FAMILY_NAMES[img.family] ?? img.name.replace(/\s+\d.*$/, "").trim() ?? img.family;
93	}
94	
95	function Stepper({ step, steps }: { step: number; steps: string[] }) {
96	  return (
97	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
98	      {steps.map((s, i) => (
99	        <div key={s} className="flex items-center gap-2">
100	          <span
101	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
102	              i === step ? "border-brand-400 bg-brand-500/20 text-brand-200"
103	                : i < step ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
104	                  : "border-white/10 text-slate-500"
105	            }`}
106	          >
107	            {i < step ? "✓" : i + 1}
108	          </span>
109	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
110	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
111	        </div>
112	      ))}
113	    </div>
114	  );
115	}
116	
117	export function DeployWizard({
118	  plans, images, nodes, sshKeys, isAdmin, balanceCents, dedicatedIpAvailable, dedicatedIpPriceCents,
119	  extraDiskPriceCentsPerGb = 0,
120	  backupPlusPriceCents = 0,
121	  defaultPlanId, defaultTermMonths,
122	  promoPercent = 0, promoLabel,
123	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
124	  taxRatePercent = 0, taxCountry = "",
125	}: {
126	  plans: Plan[]; images: Image[]; nodes: NodeOpt[];
127	  sshKeys: { id: string; name: string }[]; isAdmin: boolean; balanceCents: number;
128	  dedicatedIpAvailable?: boolean; dedicatedIpPriceCents?: number;
129	  /**
130	   * Price per GB per month for extra ROOT DISK (admin setting
131	   * `extra_disk_gb_price_cents`). Priced over the term exactly like the dedicated
132	   * IP add-on, so the maths here matches lib/order.ts orderQuote byte-for-byte.
133	   * 0 hides the upsell entirely.
134	   */
135	  extraDiskPriceCentsPerGb?: number;
136	  /**
137	   * Monthly price of the Plus backup-retention tier (admin setting
138	   * `backup_plus_price_cents`). Priced over the term like the other add-ons so this
139	   * matches lib/order.ts orderQuote byte-for-byte.
140	   */
141	  backupPlusPriceCents?: number;
142	  /**
143	   * Plan pre-selected on step 1, from the `default_plan_slug` admin setting.
144	   *
145	   * An **id**, not the slug the setting stores: this component's `Plan` type carries no
146	   * slug, so matching here would mean widening the payload or matching on `name`. The
147	   * page resolves slug → id against the very array it passes down, so any id arriving
148	   * here is guaranteed to be in `plans`; a stale slug (plan renamed, or deactivated)
149	   * arrives as `undefined` and the wizard falls back to the first plan rather than
150	   * opening with nothing selected and no price on the Review step.
151	   */
152	  defaultPlanId?: string;
153	  /**
154	   * Billing term pre-selected on the Review step, in MONTHS, from `default_term`.
155	   *
156	   * Guaranteed by `defaultTermMonths()` to be one of `VPS_TERMS`. That guarantee is
157	   * load-bearing: the term buttons below are rendered straight from `VPS_TERMS` and
158	   * highlight on `termMonths === t.months`, so an unlisted value (the old setting's
159	   * "quarterly", say) would render a Review step with no term highlighted while the
160	   * hidden `termMonths` field still posted it — and `vpsTerm()` silently falls back to
161	   * monthly, so the customer would be charged for a term nothing on screen showed.
162	   */
163	  defaultTermMonths?: number;
164	  /** Active intro-promo discount (%) on the FIRST term — matches what payAndDeploy charges. */
165	  promoPercent?: number; promoLabel?: string;
166	  /**
167	   * The admin ANNUAL discount (`annual_discount_percent`), resolved server-side and
168	   * passed in so the Annual term card's price, savings and `−X%` badge are the REAL
169	   * configured rate — the same one lib/order.ts charges and renewalCharge renews at.
170	   * Threaded into `renewalQuote` below so displayed === charged === renewed. Only
171	   * affects the 12-month card; every other term keeps its fixed rate.
172	   */
173	  annualDiscountPct?: number;
174	  /**
175	   * Destination VAT/GST rate (%) for THIS customer's billing country (Finding 1),
176	   * resolved server-side (lib/tax.ts taxContextForUser). 0 (the default, and the case
177	   * for any customer with no billing country on file) adds no tax and leaves the total
178	   * exactly as before. When > 0 the summary shows a tax line and `dueCents` is made
179	   * tax-inclusive, so what is shown here === what payAndDeploy charges.
180	   */
181	  taxRatePercent?: number;
182	  taxCountry?: string;
183	}) {
184	  const [state, action, pending] = useActionState(
185	    payAndDeploy,
186	    {} as { error?: string; checkout?: { clientSecret: string; publishableKey: string } },
187	  );
188	  // The embedded Stripe session to mount in a modal on THIS page (no redirect),
189	  // set only on an explicit Deploy submit (see submittedRef below).
190	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
191	  // DISPLAY-ONLY price formatter. In USD it renders exactly as before (byte-for-byte
192	  // — the 2-decimal `usd()` style); any other selected display currency converts the
193	  // USD-cents amount for on-screen reference only. Every value posted to payAndDeploy
194	  // stays USD cents (the hidden fields carry selections, not money). See the
195	  // display/charge boundary note in lib/currency.ts.
196	  const { currency, rate } = useCurrency();
197	  const money = (c: number) =>
198	    currency === DEFAULT_CURRENCY ? usd(c) : convertAndFormat(c, currency, rate);
199	  // Apply the first-term promo to any regular price, mirroring promoPriceCents()
200	  // in lib/promotions.ts so the wizard's displayed price === the checkout charge.
201	  const hasPromo = promoPercent > 0;
202	  const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));
203	  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit. The flag is
204	  // armed in the Deploy button's onClick (and the Enter-on-final-step path) and
205	  // consumed here, so a stale `checkoutUrl` in state can never redirect on its own —
206	  // e.g. after a back-button remount (ref starts false) or an unrelated re-render.
207	  const submittedRef = useRef(false);
208	  useEffect(() => {
209	    if (state?.checkout && submittedRef.current) {
210	      submittedRef.current = false;
211	      // The "vps" conversion is fired at FULFILMENT (PurchaseTracker, with the real
212	      // charged value + transaction_id) — NOT here at checkout-start, which would
213	      // count customers who abandon at the payment step.
214	      setCheckoutSession(state.checkout);
215	    }
216	    // `dueCents` is derived state read only inside the fire-and-forget tracking call;
217	    // opening the modal depends only on `state`.
218	    // eslint-disable-next-line react-hooks/exhaustive-deps
219	  }, [state]);
220	  const multiNode = nodes.length > 1;
221	  const steps = ["Plan", ...(multiNode ? ["Location"] : []), "Install", "Add-ons", "Access", "Review"];
222	  const [step, setStep] = useState(0);
223	
224	  // Deploy-funnel: record reaching each wizard step (de-duped per session in the
225	  // helper) so the admin funnel shows how far people get.
226	  useEffect(() => {
227	    trackDeployStep("vps", steps[step] ?? String(step), step);
228	    // steps content is stable; fire on step change only.
229	    // eslint-disable-next-line react-hooks/exhaustive-deps
230	  }, [step]);
231	
232	  // Deploy-funnel: when payAndDeploy returns an error, record it against the
233	  // current step so a BUG/provision failure is distinguishable from abandonment.
234	  useEffect(() => {
235	    if (state?.error) trackDeployError("vps", steps[step] ?? "Review", step, "ORDER_ERROR", state.error);
236	    // eslint-disable-next-line react-hooks/exhaustive-deps
237	  }, [state?.error]);
238	
239	  const [planId, setPlanId] = useState(defaultPlanId ?? plans[0]?.id ?? "");
240	  const [nodeId, setNodeId] = useState(nodes[0]?.id ?? "");
241	  const [imageId, setImageId] = useState(images.find((i) => i.category === "PLAIN_OS")?.id ?? images[0]?.id ?? "");
242	  const [tab, setTab] = useState<string>("os");
243	  const [modalFamily, setModalFamily] = useState<string | null>(null);
244	  const [q, setQ] = useState("");
245	  const [addons, setAddons] = useState({ malware: false, backup: false, docker: false });
246	  const [dedicatedIp, setDedicatedIp] = useState(false);
247	  // Backup RETENTION tier: "FREE" (keep 2, included) or "PLUS" (keep 7, paid).
248	  const [backupTier, setBackupTier] = useState<"FREE" | "PLUS">("FREE");
249	  // Extra ROOT DISK bought up front. One-way: this space can never be removed
250	  // later, which the Add-ons card and the Review step both state before payment.
251	  const [extraDiskGB, setExtraDiskGB] = useState(0);
252	  const [hostname, setHostname] = useState("");
253	  const [pubKey, setPubKey] = useState("");
254	  const [free, setFree] = useState(false);
255	  const [termMonths, setTermMonths] = useState(defaultTermMonths ?? VPS_TERMS[0].months);
256	  // Apply the wallet balance by default whenever there's something to apply.
257	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
258	  // Checkout promo code. `couponApplied` holds the server-verified discount so the
259	  // displayed total matches what placeOrder charges; it is cleared whenever the
260	  // selection changes (a "Starter only" code stops applying if they switch plans).
261	  const [couponInput, setCouponInput] = useState("");
262	  const [couponApplied, setCouponApplied] = useState<{ code: string; label: string; discountCents: number } | null>(null);
263	  const [couponMsg, setCouponMsg] = useState("");
264	  const [couponBusy, setCouponBusy] = useState(false);
265	  // Set when we come back from a cancelled Stripe Checkout, so the banner can
266	  // say what happened instead of leaving the customer on a silently reset form.
267	  const [restoredAfterCancel, setRestoredAfterCancel] = useState(false);
268	
269	  /**
270	   * Keep the customer's choices alive across the Stripe round-trip.
271	   *
272	   * Cancelling on Stripe's page hard-navigates back to
273	   * `/dashboard/deploy?canceled=1`, which remounts this component from scratch:
274	   * plan, image, add-ons, disk slider, hostname and term all gone. `?canceled=1`
275	   * was read by nothing, so there was no explanation either — the customer just
276	   * found an empty wizard and had to guess whether they had been charged.
277	   *
278	   * sessionStorage is per-tab and survives that navigation where `useState`
279	   * cannot. The draft is written on every change and read back ONLY on a
280	   * `?canceled=1` return, then deleted — a draft that reappeared on some later
281	   * visit would be its own surprise.
282	   *
283	   * No root password is drafted or submitted: provisioning always generates one
284	   * server-side and shows it on the server page. There is no field to preserve.
285	   */
286	  useEffect(() => {
287	    let canceled = false;
288	    try {
289	      canceled = new URLSearchParams(window.location.search).get("canceled") === "1";
290	    } catch {
291	      /* no URL access — fall through as a normal mount */
292	    }
293	    if (!canceled) return;
294	    let d: Draft | null = null;
295	    try {
296	      const raw = sessionStorage.getItem(DRAFT_KEY);
297	      sessionStorage.removeItem(DRAFT_KEY);
298	      if (raw) d = JSON.parse(raw) as Draft;
299	    } catch {
300	      d = null;
301	    }
302	    setRestoredAfterCancel(true);
303	    if (!d) return;
304	    // Every id is re-checked against the props actually rendered: a plan can be
305	    // deactivated or an image retired while the customer is on Stripe's page, and
306	    // selecting an id that is no longer in the list would show a blank Review
307	    // step with no price on it.
308	    if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
309	    if (nodes.some((n) => n.id === d.nodeId)) setNodeId(d.nodeId);
310	    if (images.some((i) => i.id === d.imageId)) setImageId(d.imageId);
311	    if (TABS.some((t) => t.key === d.tab)) setTab(d.tab);
312	    if (d.addons) setAddons({ malware: !!d.addons.malware, backup: !!d.addons.backup, docker: !!d.addons.docker });
313	    setDedicatedIp(!!d.dedicatedIp);
314	    if (Number.isFinite(d.extraDiskGB)) setExtraDiskGB(d.extraDiskGB);
315	    if (typeof d.hostname === "string") setHostname(d.hostname);
316	    if (typeof d.pubKey === "string") setPubKey(d.pubKey);
317	    if (VPS_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
318	    setUseWallet(!!d.useWallet && balanceCents > 0);
319	    if (Number.isInteger(d.step) && d.step >= 0 && d.step < steps.length) setStep(d.step);
320	    // Mount-only: this restores a one-shot draft and must never re-run.
321	    // eslint-disable-next-line react-hooks/exhaustive-deps
322	  }, []);
323	
324	  useEffect(() => {
325	    try {
326	      const draft: Draft = {
327	        step, planId, nodeId, imageId, tab, addons, dedicatedIp,
328	        extraDiskGB, hostname, pubKey, termMonths, useWallet,
329	      };
330	      sessionStorage.setItem(DRAFT_KEY, JSON.stringify(draft));
331	    } catch {
332	      /* storage disabled or full — the wizard still works, it just cannot
333	         survive the Stripe round-trip. Never break the order over this. */
334	    }
335	  }, [step, planId, nodeId, imageId, tab, addons, dedicatedIp, extraDiskGB, hostname, pubKey, termMonths, useWallet]);
336	
337	  const plan = plans.find((p) => p.id === planId);
338	  const image = images.find((i) => i.id === imageId);
339	
340	  const activeTab = TABS.find((t) => t.key === tab) ?? TABS[0];
341	
342	  // Images in the active tab, filtered by search.
343	  const tabImages = useMemo(() => {
344	    const needle = q.trim().toLowerCase();
345	    return images.filter(
346	      (i) => activeTab.match(i) && (needle === "" || (i.name + " " + i.version).toLowerCase().includes(needle)),
347	    );
348	  }, [images, activeTab, q]);
349	
350	  // OS tab: group images into one card per family (each with its versions).
351	  const osFamilies = useMemo<FamilyGroup[]>(() => {
352	    const map = new Map<string, FamilyGroup>();
353	    for (const i of tabImages) {
354	      const g = map.get(i.family) ?? { family: i.family, name: osFamilyName(i), logo: i.logo, versions: [] };
355	      g.versions.push(i);
356	      map.set(i.family, g);
357	    }
358	    for (const g of map.values()) g.versions.sort((a, b) => b.version.localeCompare(a.version, undefined, { numeric: true }));
359	    return [...map.values()];
360	  }, [tabImages]);
361	
362	  const openFamily = (g: FamilyGroup) => {
363	    if (g.versions.length === 1) setImageId(g.versions[0].id);
364	    else setModalFamily(g.family);
365	  };
366	  const modalGroup = modalFamily ? osFamilies.find((g) => g.family === modalFamily) : undefined;
367	
368	  const hostnameValid = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(hostname) && hostname.length >= 3;
369	  const planMeetsImage = !!plan && !!image && plan.ramMB >= image.minRamMB && plan.diskGB >= image.minDiskGB;
370	  const ipMonthly = dedicatedIp ? dedicatedIpPriceCents ?? 0 : 0;
371	  // Extra root disk: per-GB/month × GB, then × the term — priced exactly like the
372	  // dedicated IP (no term discount, no promo), matching lib/order.ts orderQuote.
373	  const extraDiskOffered = (extraDiskPriceCentsPerGb ?? 0) > 0;
374	  const extraDiskMonthly = extraDiskCentsAt(extraDiskGB, extraDiskPriceCentsPerGb ?? 0);
375	  const totalDiskGB = plan ? effectiveDiskGB(plan.diskGB, extraDiskGB) : 0;
376	  // Paid backup retention: Plus is a flat monthly add-on (no term discount, no
377	  // promo), priced over the term exactly like extra disk / dedicated IP.
378	  const backupUpsellOffered = (backupPlusPriceCents ?? 0) > 0;
379	  const backupMonthly = backupTier === "PLUS" ? backupPlusPriceCents ?? 0 : 0;
380	
381	  /**
382	   * What a term costs at the REGULAR rate — i.e. what a renewal of it will bill.
383	   * ONE definition, shared with the "Renew now" button on the server page and with
384	   * the action that charges it: `lib/renewal-quote.ts`.
385	   *
386	   * REAL INCIDENT (2026-07-26 rehearsal, H1): the term cards derived this
387	   * themselves and then printed the PROMO first-term total against the words
388	   * "billed every 1 yr" — "$67.96 billed every 1 yr" on a term that renews at
389	   * $97.09. `currentPromo()` never returns null (lib/promotions.ts always has an
390	   * active sale), so the recurring figure on those cards was wrong on 100% of
391	   * orders. Renewals bill the regular price with no promo — promos are first-term
392	   * introductory offers — and they DO bill the add-ons, so this is the whole
393	   * basket at the regular rate, exactly as worker/billing.ts will charge it.
394	   */
395	  // `gamePlan: null` is correct and not an oversight: this wizard sells plain VPS
396	  // plans. Game servers are ordered through their own flow (lib/actions-gameplans.ts)
397	  // at a flat all-in price and never reach these term cards.
398	  const regularTermCents = (months: number) =>
399	    plan
400	      ? renewalQuote(
401	          {
402	            termMonths: months,
403	            extraDiskGB: extraDiskGB,
404	            plan: { name: plan.name, priceCents: plan.priceCents },
405	            gamePlan: null,
406	            dedicatedIp: dedicatedIp ? {} : null,
407	            backupTier: "FREE",
408	          },
409	          {
410	            ipMonthlyCents: dedicatedIpPriceCents ?? 0,
411	            extraDiskPerGbCents: extraDiskPriceCentsPerGb ?? 0,
412	            // The backup add-on is priced separately via addonTermCentsFor below,
413	            // so the plan term card prices FREE here to avoid double-counting.
414	            backupPlusCents: 0,
415	            // The Annual card prices against the LIVE admin discount, so what the
416	            // card shows for the 12-month term is exactly what checkout charges and
417	            // the renewal sweep bills.
418	            annualDiscountPct,
419	          },
420	        ).totalCents
421	      : 0;
422	  /**
423	   * Effective per-month price of ANY plan at a given term — the plan's term total
424	   * (no add-ons) divided by the months. Priced through the SAME renewalQuote formula
425	   * checkout and the renewal sweep use, so the "/mo" shown on the Plan step === what is
426	   * charged. Used to make the Plan-step cards reflect the term the customer picks, so a
427	   * longer commitment visibly lowers the monthly number right where they choose the plan.
428	   */
429	  const planMonthlyAtTerm = (planPriceCents: number, months: number) =>
430	    Math.round(
431	      renewalQuote(
432	        {
433	          termMonths: months,
434	          extraDiskGB: 0,
435	          plan: { name: "", priceCents: planPriceCents },
436	          gamePlan: null,
437	          dedicatedIp: null,
438	          backupTier: "FREE",
439	        },
440	        { ipMonthlyCents: 0, extraDiskPerGbCents: 0, backupPlusCents: 0, annualDiscountPct },
441	      ).netCents / Math.max(1, months),
442	    );
